using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UI;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using ElDespacho;
public class ProfileGameplayProbe:MonoBehaviour {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic; DespachoGame g;DeskMenus m;AccessController a; Mouse mouse;string dir;List<string> log=new List<string>();
 AccessPreferences P=>AccessPreferences.Current;
 void Check(bool ok,string s){log.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(dir+"/results.txt",log);if(!ok)throw new Exception(s);}
 void Call(string n,params object[] args)=>typeof(DespachoGame).GetMethod(n,F).Invoke(g,args);
 object Get(string n)=>typeof(DespachoGame).GetField(n,F).GetValue(g);
 IEnumerator Tick(){yield return null;yield return null;yield return null;Canvas.ForceUpdateCanvases();}
 Vector2 Center(Transform t)=>RectTransformUtility.WorldToScreenPoint(null,t.TransformPoint(((RectTransform)t).rect.center));
 IEnumerator Click(Vector2 pos){InputSystem.QueueStateEvent(mouse,new MouseState{position=pos});yield return Tick();InputSystem.QueueStateEvent(mouse,new MouseState{position=pos}.WithButton(MouseButton.Left));yield return Tick();InputSystem.QueueStateEvent(mouse,new MouseState{position=pos});yield return Tick();yield return new WaitForSecondsRealtime(.35f);}
 IEnumerator Shot(string s){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();if(t){File.WriteAllBytes(dir+"/"+s+".png",t.EncodeToPNG());Destroy(t);}}
 string State(){var s=g.CaptureSave();s.utcTicks=1;return JsonUtility.ToJson(s);}
 IEnumerator Start(){bool combined=SessionState.GetBool("CombinedGameplay",false);SessionState.SetBool("CombinedGameplay",false);dir="Logs/Profiles-"+DeskMenus.Version+(combined?"-Combined":"");Directory.CreateDirectory(dir);Application.logMessageReceived+=(s,st,t)=>{if(t==LogType.Exception||t==LogType.Error){File.AppendAllText(dir+"/results.txt",s+st);EditorApplication.Exit(1);}};yield return Tick();a=AccessController.Instance;g=a.GetComponent<DespachoGame>();m=a.GetComponent<DeskMenus>();var settings=Instantiate(InputSystem.settings);settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=settings;mouse=InputSystem.AddDevice<Mouse>();DeskPreferences.Current.tutorial=false;DeskPreferences.Current.autosave=false;m.Resume();g.StartFromMenu();Call("ShowOffice");yield return Tick();
 if(combined){P.ToggleProfile(0,false);yield return Tick();}var baseline=JsonUtility.ToJson(P);File.WriteAllText(dir+"/preferences-before.json",baseline);
 var d=g.GetComponentInChildren<DeskDocument>();yield return Shot("off");yield return Click(Center(d.transform));Check(!d.AccessSelected&&!d.CanDecide,"OFF click does not select or open; drag remains required");
 P.ToggleProfile(1,false);P.Save();File.WriteAllText(dir+"/preferences-interaction.json",JsonUtility.ToJson(P));Check(P.simpleDocuments&&P.largeTargets,"interaction profile enables clicks and large targets");yield return Tick();yield return Shot("interaction-idle");
 if(DeskMenus.Version=="v0.9.13-prototipo") {var hit=d.GetComponent<AccessHitPadding>();Check(hit!=null,"document has enlarged pointer surface");var rect=(RectTransform)d.transform;var edge=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(new Vector2(rect.rect.xMin-12,0)));Check(hit.Contains(edge)&&!RectTransformUtility.RectangleContainsScreenPoint(rect,edge),"document enlarged area reaches beyond original bounds");yield return Click(edge);Check(d.AccessSelected,"click in added document area selects");a.Escape();}
 yield return Click(Center(d.transform));Check(d.AccessSelected&&!d.CanDecide,"ON real input click selects without opening");yield return Shot("interaction-selected");Check(a.Escape()&&!d.AccessSelected,"ESC route cancels selection");yield return Click(Center(d.transform));var tray=g.GetComponentsInChildren<Transform>().First(t=>t.name=="ReadingZone");yield return Click(Center(tray));Check(d.CanDecide&&(bool)Get("documentOpened"),"second mouse input click opens without dragging");yield return Shot("interaction-open");var stamp=g.GetComponentsInChildren<StampTool>().First();if(DeskMenus.Version=="v0.9.13-prototipo"){var rect=(RectTransform)stamp.transform;var edge=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(new Vector2(rect.rect.xMin-12,0)));Check(stamp.GetComponent<AccessHitPadding>().Contains(edge),"stamp enlarged area exists");yield return Click(edge);Check(a.SelectedStamp==stamp,"click in added stamp area selects");a.Escape();}
 yield return Click(Center(stamp.transform));Check(a.SelectedStamp==stamp&&!(bool)Get("cardAnswered"),"stamp click previews without deciding");Check(a.Escape()&&a.SelectedStamp==null,"cancel stamp without deciding");yield return Click(Center(stamp.transform));yield return Click(Center(d.transform));Check((bool)Get("cardAnswered"),"paper click executes decision through original rules");var decided=State();stamp.AccessApply();Check(decided==State(),"duplicate decision rejected");yield return Shot("interaction-result");Call("ArchiveCard");yield return new WaitForSecondsRealtime(.4f);yield return Tick();d=g.GetComponentInChildren<DeskDocument>();Check(d!=null&&!d.CanDecide,"next document available after result");P.ToggleProfile(1,false);yield return Tick();Check(!P.simpleDocuments&&P.largeTargets==JsonUtility.FromJson<AccessPreferences>(baseline).largeTargets,"interaction profile restores prior large-target preference");yield return Click(Center(d.transform));Check(!d.CanDecide&&!d.AccessSelected,"OFF again requires dragging");
 P.ToggleProfile(2,false);P.Save();yield return Tick();File.WriteAllText(dir+"/preferences-comprehension.json",JsonUtility.ToJson(P));Check(P.simpleLanguage&&P.navigationHelp&&P.symbols&&P.glossary,"guided profile enables four supports without enabling tutorial globally");yield return Shot("guided");string campaign=State();
 if(DeskMenus.Version=="v0.9.13-prototipo"){
  var note=g.GetComponentInChildren<OfficeAccessGuidance>();Check(note!=null,"guided adviser integrated into illustrated office");string visible=string.Join("\n",note.GetComponentsInChildren<Text>().Select(t=>t.text));Check(visible.Contains("bandeja derecha")&&visible.Contains("Estabilidad: orden")&&visible.Contains("Seguridad: defensa")&&visible.Contains("Prosperidad: economía"),"guided note explains next action and all indicators");Check(visible.Contains("[>]")&&visible.Contains("[S]")&&visible.Contains("GLOSARIO"),"symbols and glossary visible without reader or active tutorial");var help=note.GetComponentsInChildren<Button>().First(b=>b.name=="GuidedHelp");yield return Click(Center(help.transform));yield return Tick();Check(m.IsVisible&&m.PageName=="Consulta","help mouse input opens actual tutorial consultation");m.Resume();a.ClosePanels();yield return Tick();var glossary=note.GetComponentsInChildren<Button>().First(b=>b.name=="GuidedGlossary");yield return Click(Center(glossary.transform));yield return Tick();Check(a.CustomPage=="Glosario","glossary mouse input opens actual consultation");a.ClosePanels();m.Resume();yield return Tick();Check(State()==campaign,"consultations preserve campaign and tutorial progress");
 }
var texts=string.Join("\n",g.GetComponentsInChildren<Text>().Where(t=>a.IsSource(t.transform)).Select(t=>t.text));File.WriteAllText(dir+"/guided-visible.txt",texts);P.ToggleProfile(2,false);yield return Tick();yield return Shot("guided-off");Check(State()==campaign,"guided presentation leaves campaign unchanged");Check(!P.simpleLanguage&&!P.navigationHelp&&!P.symbols&&!P.glossary,"guided profile reversible");if(DeskMenus.Version=="v0.9.13-prototipo")Check(!g.GetComponentInChildren<OfficeAccessGuidance>().GetComponentsInChildren<Button>().Any(),"guided buttons removed on reversal");
 P.ToggleProfile(1,false);P.ToggleProfile(2,false);P.Save();DeskPreferences.Current.Save();File.WriteAllText("Logs/ProfileGameplay-dir.txt",DeskPreferences.TestDirectory);File.WriteAllText("Logs/ProfileGameplay-expected.txt",JsonUtility.ToJson(P));Check(!a.IsReadingView,"profiles do not open reading view");InputSystem.RemoveDevice(mouse);log.Add("COMPLETE real Play Mode with simulated InputSystem mouse; no physical device or comprehension test");File.WriteAllLines(dir+"/results.txt",log);EditorApplication.Exit(0);
 }
}
public static class ProfileGameplayRunner {
 public static void RunCombined(){SessionState.SetBool("CombinedGameplay",true);Run();}
 public static void Run(){SessionState.SetBool("ProfileGameplay",true);SessionState.SetString("ProfileGameplayDir",Path.Combine(Path.GetTempPath(),"DespachoProfiles-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 public static void Restart(){DeskPreferences.TestDirectory=File.ReadAllText("Logs/ProfileGameplay-dir.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=JsonUtility.ToJson(AccessPreferences.Current)==File.ReadAllText("Logs/ProfileGameplay-expected.txt");File.WriteAllText("Logs/ProfileGameplay-restart.txt",ok?"PASS full preferences and both profiles survive separate process":"FAIL persistence");EditorApplication.Exit(ok?0:1);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(!SessionState.GetBool("ProfileGameplay",false))return;DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("ProfileGameplayDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("ProfileGameplay",false))return;SessionState.SetBool("ProfileGameplay",false);new GameObject("ProfileGameplayProbe").AddComponent<ProfileGameplayProbe>();}
}
#endif
